      "path": "src/client/effort/directory.ts",
      "content": "/**\n * 客户端目录服务的最小结构面 —— 本插件只依赖这些成员，不 import 任何\n * DSH 运行时包（纯类型 import 会在打包时被擦除，因此客户端产物没有\n * DSH 模块请求，无需 dsh.client.external）。\n *\n * 0.1.5 起，模型目录与档位写入不再走 `connection.api.sessions.models/selectModel`\n * 这两个直连 RPC（ConnectionHandle 已不暴露 `.api`），而是走\n * `ctx.modelDirectories`（ModelDirectoryResolver）暴露的每会话共享目录：\n * 同一个 store 同时驱动 /model 弹层与输入框上方的模型座位，写入走\n * `directory.select(...)`。0.2.1 的 select 改为返回 RemoteResult，目录另带\n * routable 表示当前模型是否可用；本插件同时兼容旧版的 Promise<void>。\n */\n\n/** 一档推理等级（宿主目录返回的 effort 条目）。 */\nexport interface EffortLevel {\n  id: string\n  name: string\n  description?: string\n}\n\n/** 目录里的一个模型。 */\nexport interface DirectoryModel {\n  id: string\n  name?: string\n  /** 适配器声明的可选推理档位；缺失表示该模型没有原生多档推理。 */\n  reasoning?: {\n    efforts?: readonly EffortLevel[]\n    defaultEffort?: string\n  }\n}\n\n/** 一个提供方分组。 */\nexport interface DirectoryGroup {\n  id: string\n  name?: string\n  models: readonly DirectoryModel[]\n}\n\n/** 一次完整的模型 + 档位选择。 */\nexport interface DirectorySelection {\n  provider: string\n  model: string\n  reasoningEffort?: string\n}\n\n/** 目录快照（ModelDirectoryState 的结构子集）。 */\nexport interface DirectoryState {\n  /** 生效选择：会话投影或宿主默认值。 */\n  current: DirectorySelection | null\n  /** 0.2.1：当前选择是否仍在目录中；null 表示会话投影尚未就绪。 */\n  routable?: boolean | null\n  /** 已加载的提供方分组。 */\n  groups: readonly DirectoryGroup[]\n  /** 进行中的操作生命周期。 */\n  status?: 'idle' | 'loading' | 'ready' | 'selecting' | 'error'\n  /** 整请求或选择失败的文案。 */\n  error?: string | null\n}\n\n/** 一个会话的共享目录。 */\nexport interface ModelDirectoryLike {\n  readonly store: {\n    getSnapshot(): DirectoryState\n    subscribe(listener: () => void): () => void\n  }\n  /** 确保宿主目录已加载。 */\n  load(): Promise<unknown>\n  /** 提交 provider/model/reasoningEffort 选择。 */\n  select(selection: DirectorySelection): Promise<void | {\n    ok: true\n    value?: unknown\n  } | {\n    ok: false\n    error: { code: string; message: string }\n  }>\n}\n\n/** `ctx.modelDirectories`。 */\nexport interface ModelDirectoriesLike {\n  directoryFor(sessionId: string): ModelDirectoryLike\n}\n\n/** 会话目录里的一行（SessionSummary 的结构子集）。 */\nexport interface SessionRowLike {\n  id?: string\n  /** 本地持有计数；0.2.0 的 mainView 计数 > 0 即当前主视图会话。 */\n  retainedBy?: Partial<Record<string, number | undefined>>\n}\n\n/** 会话目录快照（SessionListState 的结构子集，兼容 0.1.x / 0.2.0）。 */\nexport interface SessionListLike {\n  /** 0.1.x 直出的当前会话 id；0.2.0 起移除。 */\n  current?: string\n  /** 0.2.0 的目录行（键为会话 id）。 */\n  byId?: Record<string, SessionRowLike>\n}\n\n/** `ctx.sessions`（只用到当前会话 id）。 */\nexport interface SessionsLike {\n  readonly list: {\n    getSnapshot(): SessionListLike\n    subscribe?(listener: () => void): () => void\n  }\n}\n\n/** 兼容旧版 rejection 与 0.2.1 的 RemoteResult，且接住同步抛错。 */\nexport async function selectEffort(directory: ModelDirectoryLike, selection: DirectorySelection): Promise<void> {\n  const result = await directory.select(selection)\n  if (result?.ok === false) throw new Error(`${result.error.code}: ${result.error.message}`)\n}\n\n/** Wait for a real catalog refresh without submitting against an unknown model. */\nfunction readyForSelection(directory: ModelDirectoryLike): Promise<DirectoryState> {\n  return new Promise((resolve, reject) => {\n    let stop: (() => void) | undefined\n    let settled = false\n    const finish = (error?: Error, state?: DirectoryState): void => {\n      if (settled) return\n      settled = true\n      clearTimeout(timeout)\n      stop?.()\n      if (error !== undefined) reject(error)\n      else resolve(state!)\n    }\n    const read = (): void => {\n      const state = snapshotOf(directory)\n      if (state !== null && state.current !== null && state.routable !== null\n        && (state.status !== 'error' || state.routable === true)\n        && state.status !== 'loading' && state.status !== 'idle') {\n        finish(undefined, state)\n      } else if (state?.status === 'error') {\n        finish(new Error(state.error ?? 'Model directory refresh failed'))\n      }\n    }\n    const timeout = setTimeout(() => finish(new Error('Model directory refresh timed out')), 10000)\n    stop = directory.store.subscribe(read)\n    if (settled) stop()\n    else read()\n  })\n}\n\n/**\n * One active selection plus the latest requested value. Settings updates can\n * refresh the whole DSH catalog mid-drag; wait for it, then validate the actual\n * model again. Never replay a backlog of obsolete intermediate effort levels.\n * A committed request can finish after its panel closes, in its owning Session.\n */\nexport function effortWriter(directory: ModelDirectoryLike): (selection: DirectorySelection) => Promise<void> {\n  let pending: DirectorySelection | undefined\n  let active: Promise<void> | undefined\n  const drain = async (): Promise<void> => {\n    while (pending !== undefined) {\n      let submitted = false\n      try {\n        const state = await readyForSelection(directory)\n        const selection = pending\n        pending = undefined\n        submitted = true\n        if (state.current?.provider !== selection.provider || state.current.model !== selection.model\n          || state.routable === false) {\n          throw new Error('The selected model changed before the effort could be saved')\n        }\n        await selectEffort(directory, selection)\n      } catch (error) {\n        if (!submitted) {\n          pending = undefined\n          throw error\n        }\n        // An older failure must not discard a newer pointer/keyboard request.\n        if (pending === undefined) throw error\n      }\n    }\n  }\n  return (selection) => {\n    pending = selection\n    active ??= drain().finally(() => { active = undefined })\n    return active\n  }\n}\n\n/**\n * 解析当前主视图会话 id。0.1.x 直接读 `list.current`；0.2.0 该字段移除\n * （「导航归视图所有」），官方 uiSession 以 `retainedBy.mainView > 0`\n * 判定当前会话，这里跟随同一判定，并保留旧字段兜底。\n */\nexport function currentSessionId(sessions: SessionsLike): string | undefined {\n  let snapshot: SessionListLike\n  try {\n    snapshot = sessions.list.getSnapshot()\n  } catch {\n    return undefined\n  }\n  const direct = snapshot.current\n  if (typeof direct === 'string' && direct.length > 0) return direct\n  for (const [key, row] of Object.entries(snapshot.byId ?? {})) {\n    if ((row?.retainedBy?.mainView ?? 0) > 0) {\n      return typeof row?.id === 'string' && row.id.length > 0 ? row.id : key\n    }\n  }\n  return undefined\n}\n\n/** 安全读取目录快照：目录可能尚未装配完整。 */\nexport function snapshotOf(directory: ModelDirectoryLike): DirectoryState | null {\n  try {\n    return directory.store.getSnapshot() ?? null\n  } catch {\n    return null\n  }\n}\n"
